const vec & AWGNTables::getMMIBTable (ModulationScheme_E mosc)
{
  map<ModulationScheme_E,int>::iterator it=moscToIndex.find (mosc);
  if(it!=moscToIndex.end())
    return mmibTable(moscToIndex[mosc]);
  else
  {
    cout<<"[both:] is not a  proper cqi class AWGNTables getMMIBTable()"<<endl;
    exit(2);
  }
}

void CQIidxMapping(bool is256QAMEnabled, int CQIidx,ModulationScheme_E &mosc)
{
  CodeRate_E cora;
  if(!is256QAMEnabled)
  {
  switch(CQIidx)
    {
      case 1: {mosc = _MODULATION_SCHEME_QPSK_; cora = _CODE_RATE_78b1024_; break;}
      case 2: {mosc = _MODULATION_SCHEME_QPSK_; cora = _CODE_RATE_120b1024_; break;}
      case 3: {mosc = _MODULATION_SCHEME_QPSK_; cora = _CODE_RATE_193b1024_; break;}
      case 4: {mosc = _MODULATION_SCHEME_QPSK_; cora = _CODE_RATE_308b1024_; break;}
      case 5: {mosc = _MODULATION_SCHEME_QPSK_; cora = _CODE_RATE_449b1024_; break;}
      case 6: {mosc = _MODULATION_SCHEME_QPSK_; cora = _CODE_RATE_602b1024_; break;}
      
      case 7: {mosc = _MODULATION_SCHEME_16_QAM_; cora = _CODE_RATE_378b1024_; break;}
      case 8: {mosc = _MODULATION_SCHEME_16_QAM_; cora = _CODE_RATE_490b1024_; break;}
      case 9: {mosc = _MODULATION_SCHEME_16_QAM_; cora = _CODE_RATE_616b1024_; break;}
	
      case 10: {mosc = _MODULATION_SCHEME_64_QAM_; cora = _CODE_RATE_466b1024_; break;}
      case 11: {mosc = _MODULATION_SCHEME_64_QAM_; cora = _CODE_RATE_567b1024_; break;}
      case 12: {mosc = _MODULATION_SCHEME_64_QAM_; cora = _CODE_RATE_666b1024_; break;}
      case 13: {mosc = _MODULATION_SCHEME_64_QAM_; cora = _CODE_RATE_772b1024_; break;}
      case 14: {mosc = _MODULATION_SCHEME_64_QAM_; cora = _CODE_RATE_873b1024_; break;}
      case 15: {mosc = _MODULATION_SCHEME_64_QAM_; cora = _CODE_RATE_948b1024_; break;}
      default : {cout<<" [both:] MOSC not defined for CQI index : "<<CQIidx; abort();}
    }
  }
  else
  {
    switch(CQIidx)
    {
      case 1: {mosc = _MODULATION_SCHEME_QPSK_;break;}
      case 2: {mosc = _MODULATION_SCHEME_QPSK_;break;}
      case 3: {mosc = _MODULATION_SCHEME_QPSK_;break;}
      
      case 4: {mosc = _MODULATION_SCHEME_16_QAM_;break;}
      case 5: {mosc = _MODULATION_SCHEME_16_QAM_;break;}
      case 6: {mosc = _MODULATION_SCHEME_16_QAM_;break;}
      
      case 7: {mosc = _MODULATION_SCHEME_64_QAM_;break;}
      case 8: {mosc = _MODULATION_SCHEME_64_QAM_;break;}
      case 9: {mosc = _MODULATION_SCHEME_64_QAM_;break;}
      case 10: {mosc = _MODULATION_SCHEME_64_QAM_;break;}
      case 11: {mosc = _MODULATION_SCHEME_64_QAM_;break;}
      
      case 12: {mosc = _MODULATION_SCHEME_256_QAM_;break;}
      case 13: {mosc = _MODULATION_SCHEME_256_QAM_;break;}
      case 14: {mosc = _MODULATION_SCHEME_256_QAM_;break;}
      case 15: {mosc = _MODULATION_SCHEME_256_QAM_;break;}
      default : {cout<<" [both:] MOSC not defined for CQI index : "<<CQIidx; abort();}
    }
  }
}
  
int CQIremapping(ModulationScheme_E mosc, CodeRate_E cora)
{
  
  if(mosc ==_MODULATION_SCHEME_QPSK_ && cora ==_CODE_RATE_78b1024_) return 1; 
  if(mosc ==_MODULATION_SCHEME_QPSK_ && cora ==_CODE_RATE_120b1024_) return 2;
  if(mosc ==_MODULATION_SCHEME_QPSK_ && cora ==_CODE_RATE_193b1024_) return 3;
  if(mosc ==_MODULATION_SCHEME_QPSK_ && cora ==_CODE_RATE_308b1024_) return 4;
  if(mosc ==_MODULATION_SCHEME_QPSK_ && cora ==_CODE_RATE_449b1024_) return 5;
  if(mosc ==_MODULATION_SCHEME_QPSK_ && cora ==_CODE_RATE_602b1024_) return 6;
  
  if(mosc ==_MODULATION_SCHEME_16_QAM_ && cora ==_CODE_RATE_378b1024_) return 7;
  if(mosc ==_MODULATION_SCHEME_16_QAM_ && cora ==_CODE_RATE_490b1024_) return 8;
  if(mosc ==_MODULATION_SCHEME_16_QAM_ && cora ==_CODE_RATE_616b1024_) return 9;
  
  
  if(mosc ==_MODULATION_SCHEME_64_QAM_ && cora ==_CODE_RATE_466b1024_) return 10;
  if(mosc ==_MODULATION_SCHEME_64_QAM_ && cora ==_CODE_RATE_567b1024_) return 11;
  if(mosc ==_MODULATION_SCHEME_64_QAM_ && cora ==_CODE_RATE_666b1024_) return 12; 
  if(mosc ==_MODULATION_SCHEME_64_QAM_ && cora ==_CODE_RATE_772b1024_) return 13;
  if(mosc ==_MODULATION_SCHEME_64_QAM_ && cora ==_CODE_RATE_873b1024_) return 14;
  if(mosc ==_MODULATION_SCHEME_64_QAM_ && cora ==_CODE_RATE_948b1024_) return 15;
    
  cout<<" [both:] MSC index not defined for MOSC : "<<mosc<<"\t"<<cora;
  abort();
  
}

void mcsidxMapping(bool is256QAMEnabled, bool isPiby2BPSKEnabled, int MCSidx,ModulationScheme_E &mosc,bool isDownlink)
{
  if(isDownlink)
  {
    if(!is256QAMEnabled)
    {
      if(MCSidx >=0 && MCSidx <= 9)
	mosc = _MODULATION_SCHEME_QPSK_;
      else if(MCSidx >9 && MCSidx <= 16)
	mosc = _MODULATION_SCHEME_16_QAM_;
      else if(MCSidx > 16 && MCSidx <= 28)
	mosc = _MODULATION_SCHEME_64_QAM_;
      else
      {
	cout<<"[both:] Unsupported MCSidx in mcsidxMapping() .. Aborting"<<endl;abort();
      }
    }
    else
    {
      if(MCSidx >=0 && MCSidx <= 4)
	mosc = _MODULATION_SCHEME_QPSK_;
      else if(MCSidx >4 && MCSidx <= 10)
	mosc = _MODULATION_SCHEME_16_QAM_;
      else if(MCSidx > 10 && MCSidx <= 19)
	mosc = _MODULATION_SCHEME_64_QAM_;
      else if(MCSidx > 19 && MCSidx <= 27)
	mosc = _MODULATION_SCHEME_256_QAM_;
      else
      {
	cout<<"[both:] Unsupported MCSidx in mcsidxMapping() .. Aborting"<<endl;abort();
      }
    }
  }
  else
  {
    if(!isPiby2BPSKEnabled)
    {
      if(MCSidx >=0 && MCSidx <= 9)
	mosc = _MODULATION_SCHEME_QPSK_;
      else if(MCSidx >9 && MCSidx <= 16)
	mosc = _MODULATION_SCHEME_16_QAM_;
      else if(MCSidx > 16 && MCSidx <= 27)
	mosc = _MODULATION_SCHEME_64_QAM_;
      else
      {
	cout<<"[both:] Unsupported MCSidx in mcsidxMapping() .. Aborting"<<endl;abort();
      }
    }
    else
    {
      if(MCSidx >=0 && MCSidx <= 1)
	mosc = _MODULATION_SCHEME_BPSK_;
      else if(MCSidx >1 && MCSidx <= 9)
	mosc = _MODULATION_SCHEME_QPSK_;
      else if(MCSidx >9 && MCSidx <= 16)
	mosc = _MODULATION_SCHEME_16_QAM_;
      else if(MCSidx > 16 && MCSidx <= 27)
	mosc = _MODULATION_SCHEME_64_QAM_;
      else
      {
	cout<<"[both:] Unsupported MCSidx in mcsidxMapping() .. Aborting"<<endl;abort();
      }
    }
  }
}
  
double AWGNTables::sinrToEffMMIB(vec& sinr, ModulationScheme_E mosc)
{
  
  vec MIvec;
  int indx=moscToIndex[mosc];
  vec sinrIndB=dB(sinr);
  double SINRStart=mmibBlerStartIndex(indx);
  double SINRRes=mmibBlerResolution(indx);
  vec temp1 = (sinrIndB-SINRStart)/SINRRes;
  ivec sinrIndx=round_i(temp1);
  
  ivec negIndx=find(sinrIndx<0);
  setInVec(sinrIndx,negIndx,zeros_i(negIndx.length()));
  
  ivec maxIndx=find(sinrIndx>=mmibTable(indx).length());
  setInVec(sinrIndx,maxIndx,zeros_i(maxIndx.length())+(mmibTable(indx).length()-1));
  
  MIvec=mmibTable(indx)(sinrIndx);
  
//   switch (mosc)
//   {
//     case _MODULATION_SCHEME_QPSK_:
//       MIvec=JFunction(2.0*sqrt(sinr));
//       break;
//       
//     case _MODULATION_SCHEME_16_QAM_:
//       MIvec=0.5*JFunction(0.8*sqrt(sinr)) + 0.25*JFunction(2.17*sqrt(sinr)) + 0.25*JFunction(0.965*sqrt(sinr));
//       break;
//       
//     case _MODULATION_SCHEME_64_QAM_:
//       MIvec=(1.0/3.0)*JFunction(1.47*sqrt(sinr)) +(1.0/3.0)*JFunction(0.529*sqrt(sinr)) + (1.0/3.0)*JFunction(0.366*sqrt(sinr));
//       break;
//     default:
//     {
//       cout<<"Unknown ModulationScheme_E to sinrToEffMMIB()."<<endl;abort();
//     }
//   }
//   cout<<"mmib value"<<MIvec<<endl;abort();

  return mean(MIvec);
  
}
  
