int AWGNTables::CQISelect(double &exp_spec_eff, double mmib_256, double mmib_sxfr,double mmib_sxtn,double mmib_qpsk,ivec TBsizePerCQI, bool enableCQI0)
{
    ///Note: Assuming BIT_REP_FACTOR same for the entire network
    
    ModulationScheme_E mosc;
    //   CodeRate_E cora;
    double codeRate;
    double mmib=0.0;
    vec BLER,spec_eff,ex_spec_eff;
    vec SINR;
    int cqiCount=bler.length();
    SINR.set_length(cqiCount);
    BLER.set_length(cqiCount);
    spec_eff=zeros(cqiCount)-1;
    
    int bitsPerModSymbol=0;
    for(int cqi=1;cqi<cqiCount;cqi++)
    {
        CQIidxMapping(is256QAMenabled, cqi,mosc);
        codeRate=codeRatePerCQI(cqi);
        if(mosc == _MODULATION_SCHEME_QPSK_) { mmib = mmib_qpsk; bitsPerModSymbol=2; }
        else if(mosc == _MODULATION_SCHEME_16_QAM_) { mmib = mmib_sxtn;  bitsPerModSymbol=4;}
        else if(mosc == _MODULATION_SCHEME_64_QAM_) { mmib = mmib_sxfr;  bitsPerModSymbol=6;} 
        else if(mosc == _MODULATION_SCHEME_256_QAM_) { mmib = mmib_256;  bitsPerModSymbol=8;} 
        else {cout<<"[both:] mosc values is not supported "<<mosc<<" aborting ....."<<endl;abort();}
        
        SINR(cqi) = mmibToSinr(mosc, mmib);
        
        
        BLER(cqi) = getBlerFromMmib(cqi, mmib, mosc, TBsizePerCQI(cqi));
        spec_eff(cqi) = bitsPerModSymbol * codeRate *  ( 1.0 - BLER(cqi) ) ; 
        
        if(BLER(cqi)>0.1)
            spec_eff(cqi) = -cqi;
    }
    
    ivec cqi_sorted = sort_index(spec_eff);
    ex_spec_eff=spec_eff(cqi_sorted);
    exp_spec_eff=ex_spec_eff(cqiCount-1);
    
    int cqi = cqi_sorted(cqiCount-1);
    
    //CQI 0
    if(enableCQI0 && exp_spec_eff<0)
        cqi = 0;
    
    if(exp_spec_eff<0)
        exp_spec_eff=0; 
    
    //exp_spec_eff = log2(1+inv_dB(SINR(cqi))); //Modified Type2
    
    return cqi;
    
}
int AWGNTables::CQISelect(double &exp_spec_eff,map<ModulationScheme_E,double>& MMIB,ivec TBsizePerCQI, bool enableCQI0)
{
  ///Note: Assuming BIT_REP_FACTOR same for the entire network
  
  ModulationScheme_E mosc;
//   CodeRate_E cora;
  double codeRate;
  double mmib=0.0;
  vec BLER,spec_eff,ex_spec_eff;
  vec SINR;
  int cqiCount=bler.length();
  SINR.set_length(cqiCount);
  BLER.set_length(cqiCount);
  spec_eff=zeros(cqiCount)-1;
  
  int bitsPerModSymbol=0;
  ivec possibleMosc = 2*getIntegers(1,4);
  for(int cqi=1;cqi<cqiCount;cqi++)
  {
    CQIidxMapping(is256QAMenabled, cqi,mosc);
    codeRate=codeRatePerCQI(cqi);
    if(find(possibleMosc,(int)mosc)==-1){cout<<"[both:] mosc values is not supported "<<mosc<<" aborting ....."<<endl;abort();}

    mmib = MMIB[mosc];bitsPerModSymbol = (int)mosc; 
    
    SINR(cqi) = mmibToSinr(mosc, mmib);
    
    BLER(cqi) = getBlerFromMmib(cqi, mmib, mosc, TBsizePerCQI(cqi));
    spec_eff(cqi) = bitsPerModSymbol * codeRate *  ( 1.0 - BLER(cqi) ) ; 
    
    if(BLER(cqi)>0.1)
      spec_eff(cqi) = -cqi;
  }

  ivec cqi_sorted = sort_index(spec_eff);
  ex_spec_eff=spec_eff(cqi_sorted);
  exp_spec_eff=ex_spec_eff(cqiCount-1);
  
  int cqi = cqi_sorted(cqiCount-1);

  //CQI 0
  if(enableCQI0 && exp_spec_eff<0)
    cqi = 0;

  if(exp_spec_eff<0)
    exp_spec_eff=0; 
    
  //exp_spec_eff = log2(1+inv_dB(SINR(cqi))); //Modified Type2
  
  return cqi;
  
}

int AWGNTables::mcsSelect(double& exp_spec_eff, vec& sinr, ivec tbsizeWithCRC, vec codeRate, vec spec_eff, bool isDownlink, double sinrOffsetIndB, vec targetBLER)
{
  ModulationScheme_E mosc;
  double mmib = 0.0;
  vec BLER,ex_spec_eff;
//   cout << "is256QAMenabled: " << is256QAMenabled<<endl;
  int mcsCount = (is256QAMenabled || !isDownlink)?28:29;   
  BLER.set_length(mcsCount);
  double offset=0;
  for(int mcs=0;mcs<mcsCount;mcs++)
  {
    mcsidxMapping(is256QAMenabled,isPi2BPSKenabled,mcs,mosc,isDownlink);
    mmib = sinrToEffMMIB(sinr,mosc);  
    
    //     // Selecting 64-QAM MCS is little bit conservatively 
    //     if(mosc == _MODULATION_SCHEME_64_QAM_)
    //       offset = -0.3;
    //     else
    //       offset=0;
    vec dummy;
    BLER(mcs) = getBlerFromMmibForAbstraction(codeRate(mcs), (mmibToSinr(mosc,mmib)+sinrOffsetIndB+offset), mosc, tbsizeWithCRC(mcs),dummy,codeRate(mcs));
    
    spec_eff(mcs) = spec_eff(mcs) * (1.0 - BLER(mcs));
    if(BLER(mcs) > targetBLER(mcs))
      spec_eff(mcs) = -mcs;
  }
  
  ivec mcs_sorted = sort_index(spec_eff);
  
  ex_spec_eff=spec_eff(mcs_sorted);
  exp_spec_eff=ex_spec_eff(mcsCount-1);
  
  int mcs = mcs_sorted(mcsCount-1);

  if(exp_spec_eff < 0)
  {
    exp_spec_eff = 0;
    mcs = 0;
  }
  return mcs;
}


double AWGNTables::getBlerFromMmib(int cqi, double mmib,ModulationScheme_E mosc,int tbsize)
{
  ivec codeSegments;
  double codeRate = codeRatePerCQI(cqi);
  if(txMode == _TRANSMISSION_MODE_NR_)
    codeSegments = getCodeBlockSizesForTBNR(tbsize,codeRate);
  else
    codeSegments = getCodeBlockSizesForTB(tbsize,interleaveParametersK);
  
  double effSinr = mmibToSinr(mosc,mmib);
  vec blerToReturn=zeros(codeSegments.length())-1;
  double pAllBlockSuccess=1;
  for(int seg_cnt=0;seg_cnt<codeSegments.length();seg_cnt++)
  {
    int sinr_indx = floor_i( (effSinr - snrBlerStartIndex ) / snrBlerResolution);
    if(sinr_indx<0)
    {
      sinr_indx=0;
    }
    
    if(sinr_indx>=bler(cqi).cols())
      sinr_indx=bler(cqi).cols()-1;
    
    int TBSizeIndx=find(TBSizeWithCrc,tbsize);
    if(TBSizeIndx==-1)
    {
      int closestIndx1 = findClosest(TBSizeWithCrc,codeSegments(seg_cnt));
      int closestIndx2=-1;
      if(TBSizeWithCrc(closestIndx1) > codeSegments(seg_cnt))
        closestIndx2 = closestIndx1-1;
      else
        closestIndx2 = closestIndx1+1; 
      
      if(closestIndx2==-1 || closestIndx2==TBSizeWithCrc.length())
      {
        TBSizeIndx=closestIndx1;
        
        blerToReturn(seg_cnt) =  bler(cqi)(TBSizeIndx,sinr_indx);
      }
      else
      {
        double bler1=bler(cqi)(closestIndx1,sinr_indx);
        double bler2=bler(cqi)(closestIndx2,sinr_indx);
        double finalBler = bler1 + (bler2 - bler1)*(((double)codeSegments(seg_cnt) - (double)TBSizeWithCrc(closestIndx1))/((double)TBSizeWithCrc(closestIndx2)-(double)TBSizeWithCrc(closestIndx1)));
        
        blerToReturn(seg_cnt) = finalBler;
      }
    }
    else
    {
      blerToReturn(seg_cnt) = bler(cqi)(TBSizeIndx,sinr_indx);
    }
    pAllBlockSuccess*=(1.0-blerToReturn(seg_cnt));
  }
  
  return (1.0-pAllBlockSuccess);
}

double AWGNTables::getBlerFromMmibForAbstraction(double codeRate, double effSinr, ModulationScheme_E mosc, int tbsizeWithCRC,vec &blerPerCB, double tCodeRate)
{
  ivec codeSegments;
  
  if(txMode == _TRANSMISSION_MODE_NR_)
    codeSegments = getCodeBlockSizesForTBNR(tbsizeWithCRC,tCodeRate);
  else
    codeSegments = getCodeBlockSizesForTB(tbsizeWithCRC,interleaveParametersK);
  
  ivec validCQIIndices=find(modulationSchemePerCQI,(int)mosc,true);
  vec validCodeRates=codeRatePerCQI(validCQIIndices);
  int cqi=validCQIIndices(findClosest(validCodeRates,codeRate));
  
  if(codeRatePerCQI(cqi)<codeRate && cqi!=validCQIIndices(validCQIIndices.length()-1))
    cqi = cqi+1;
  
  // No closed form expression between SINR and codeRate (Approx. formula ! )
  if((int)mosc == 2)
    effSinr=dB((codeRatePerCQI(cqi)/codeRate)*inv_dB(effSinr));
  else
    effSinr=((codeRatePerCQI(cqi)/codeRate)*(effSinr));
  
  
  vec blerToReturn=zeros(codeSegments.length())-1;
  double pAllBlockSuccess=1;
  for(int seg_cnt=0;seg_cnt<codeSegments.length();seg_cnt++)
  {
    int sinr_indx = floor_i( (effSinr - snrBlerStartIndex ) / snrBlerResolution);
    if(sinr_indx<0)
    {
      sinr_indx=0;
    }
    
    if(sinr_indx>=bler(cqi).cols())
      sinr_indx=bler(cqi).cols()-1;
    
    int TBSizeIndx=find(TBSizeWithCrc,codeSegments(seg_cnt));
    if(TBSizeIndx==-1)
    {
      int closestIndx1 = findClosest(TBSizeWithCrc,codeSegments(seg_cnt));
      int closestIndx2=-1;
      if(TBSizeWithCrc(closestIndx1) > codeSegments(seg_cnt))
        closestIndx2 = closestIndx1-1;
      else
        closestIndx2 = closestIndx1+1; 
      
      if(closestIndx2==-1 || closestIndx2==TBSizeWithCrc.length())
      {
        TBSizeIndx=closestIndx1;
        
        blerToReturn(seg_cnt) =  bler(cqi)(TBSizeIndx,sinr_indx);
      }
      else
      {
        double bler1=bler(cqi)(closestIndx1,sinr_indx);
        double bler2=bler(cqi)(closestIndx2,sinr_indx);
        double finalBler = bler1 + (bler2 - bler1)*(((double)codeSegments(seg_cnt) - (double)TBSizeWithCrc(closestIndx1))/((double)TBSizeWithCrc(closestIndx2)-(double)TBSizeWithCrc(closestIndx1)));
        blerToReturn(seg_cnt) = finalBler;
      }
    }
    else
    {
      blerToReturn(seg_cnt) = bler(cqi)(TBSizeIndx,sinr_indx);
    }
    
    pAllBlockSuccess*=(1.0-blerToReturn(seg_cnt));
  }
  blerPerCB=blerToReturn;
  return (1.0-pAllBlockSuccess);
}

double AWGNTables::getBlerForIdealAbstraction(int nTransmissions, double targetBLER)
{
  double blerToReturn = pow(targetBLER,nTransmissions);
  return blerToReturn;
}


double AWGNTables::mmibToSinr(ModulationScheme_E mosc,double effmmib){

  double sinr_eff=-100;
  double sinr_st_tmp;
  double sinr_res_tmp;
  vec snr_mmib_table_tmp;
  
  map<ModulationScheme_E,int>::iterator it=moscToIndex.find (mosc);
  if(it!=moscToIndex.end())
  {
    snr_mmib_table_tmp=mmibTable(moscToIndex[mosc]);
    sinr_st_tmp=mmibBlerStartIndex(moscToIndex[mosc]);
    sinr_res_tmp=mmibBlerResolution(moscToIndex[mosc]);
  }
  else
  {
    cout<<" [both:] No mmib table for mosc value:"<<mosc<<endl; abort();
  }
  int snr_mmib_table_buffer_size = snr_mmib_table_tmp.length(); 
  
  if(effmmib<=snr_mmib_table_tmp(0)){
    sinr_eff=sinr_st_tmp;}
  else if(effmmib>snr_mmib_table_tmp(snr_mmib_table_buffer_size-1))
    {sinr_eff=sinr_st_tmp+sinr_res_tmp*(snr_mmib_table_buffer_size-1);}
  else {
    for(int i=0;i<snr_mmib_table_buffer_size-1;i++)
    {
      if(effmmib==snr_mmib_table_tmp(i)||(effmmib>snr_mmib_table_tmp(i)&&effmmib<snr_mmib_table_tmp(i+1))){
	sinr_eff=sinr_st_tmp+(i*sinr_res_tmp);break;
      }
    }
  }
  return(sinr_eff);
}

double AWGNTables::getSINRIndBfromCQI(int CQI){
  
  double targetBLER = 0.1;

  vec SINRlinear = zeros(TBSizeWithCrc.length());
  
  for(int cnt = 0; cnt < TBSizeWithCrc.length(); cnt++)
  {
    
    vec blerVec = bler(CQI).get_row(cnt);
    int bler_indx = findClosest(blerVec,targetBLER);
    
    int shift_index = 0;
    while(blerVec(bler_indx+shift_index) > targetBLER)
      shift_index++;
    
    SINRlinear(cnt) = inv_dB(snrBlerStartIndex + (snrBlerResolution*(bler_indx-shift_index)));
  }
  
  //cout<<"SINRs : "<<dB(SINRlinear)<<" mean : "<<dB(mean(SINRlinear))<<endl;
  return dB(mean(SINRlinear));
}

double AWGNTables::getRateOffset(double rate, double powerOffsetIndB){
    
    if(rate>0.1)
    {
        vec ratePerCQI = elem_mult(to_vec(modulationSchemePerCQI),codeRatePerCQI);
        int cqi = findClosest(ratePerCQI,rate);
        int offsettedCQI = getCQIfromSINR(getSINRIndBfromCQI(cqi) + powerOffsetIndB);
        return ratePerCQI(offsettedCQI);
    }
    else
        return rate;
    
}

vec AWGNTables::getSINRIndBfromCQI(ivec CQI){
  
  vec toReturnSINR = -100*ones(CQI.length());
  
  for(int cnt = 0; cnt < CQI.length(); cnt++)
    toReturnSINR(cnt) = getSINRIndBfromCQI(CQI(cnt));
  
  return toReturnSINR;
}

Array<vec> AWGNTables::getSINRIndBfromCQI(Array<ivec> CQI){
  
  Array<vec> toReturn(CQI.length());
  for(int i = 0; i < CQI.length(); i++ )
    toReturn(i)=getSINRIndBfromCQI(CQI(i));
    
  return toReturn;
}

int AWGNTables::getCQIfromSINR(double SINRIndB){
    
    int nCQI = bler.size();
    vec SINRsPerCQI = -100*ones(nCQI);
    
    for(int cqiIndex = 1; cqiIndex<nCQI; cqiIndex++)
        SINRsPerCQI(cqiIndex) = getSINRIndBfromCQI(cqiIndex);
    
    
    int CQI = findClosest(SINRsPerCQI,SINRIndB);
        
    if(SINRIndB < SINRsPerCQI(CQI))
            CQI = CQI - 1;
        
    if(CQI < 1)
        CQI = 1;
    
    return CQI;
    
}

ivec AWGNTables::getCQIPerCWfromSINR(vec SINRperCW){
  
  ivec CQIperCW(SINRperCW.length());
  int nCQI = bler.size();
  vec SINRsPerCQI = -100*ones(nCQI);
  for(int k = 1; k<=nCQI; k++)
    SINRsPerCQI(k) = getSINRIndBfromCQI(k);
  
  for(int i = 0; i < CQIperCW.length(); i++ )
  {
    CQIperCW(i) = findClosest(SINRsPerCQI,SINRperCW(i));
    
    if(SINRperCW(i) < SINRsPerCQI(CQIperCW(i)))
      CQIperCW(i) = CQIperCW(i) - 1;
    
    if(CQIperCW(i) < 1)
      CQIperCW(i) = 1;
  }

  return CQIperCW;
  
}

double AWGNTables::sinrToEffSINRindB(vec& sinr, int modOrder){
  
  double effSinr = -100;
  
  switch(modOrder)
  {
    case 1:
      effSinr = mmibToSinr(_MODULATION_SCHEME_BPSK_,sinrToEffMMIB(sinr,_MODULATION_SCHEME_BPSK_));
      break;
    case 2:
      effSinr = mmibToSinr(_MODULATION_SCHEME_QPSK_,sinrToEffMMIB(sinr,_MODULATION_SCHEME_QPSK_));
      break;
    case 4:
      effSinr = mmibToSinr(_MODULATION_SCHEME_16_QAM_,sinrToEffMMIB(sinr,_MODULATION_SCHEME_16_QAM_));
      break;
    case 6:
      effSinr = mmibToSinr(_MODULATION_SCHEME_64_QAM_,sinrToEffMMIB(sinr,_MODULATION_SCHEME_64_QAM_));
      break;
    case 8:
      effSinr = mmibToSinr(_MODULATION_SCHEME_256_QAM_,sinrToEffMMIB(sinr,_MODULATION_SCHEME_256_QAM_));
      break;
    default:
      cout<<"Unsupported modOrder... Aborting in sinrToEffSINR()"<<endl;abort();
  }
  return effSinr;
}

