double AWGNTablesConvCoder::getErrorProbabilityForPDCCH(int aggLevel, double SinrIndB, int tPDUSizeWithCrc){
  
  double blerToReturn=1.0;
  
  int sinr_indx = floor_i( (SinrIndB - snrBlerStartIndexCC ) / snrBlerResolutionCC);
  
  if(sinr_indx<0)
    sinr_indx=0;

  int indx = find(aggLevels,aggLevel);
  
  if(sinr_indx>=blerCC(indx).cols())
    sinr_indx=blerCC(indx).cols()-1;
  
  int PDUSizeIndx=find(PDUSizeWithCrc,tPDUSizeWithCrc);
  if(PDUSizeIndx==-1)
  {
    int closestIndx1 = findClosest(PDUSizeWithCrc,tPDUSizeWithCrc);
    int closestIndx2=-1;
    if(PDUSizeWithCrc(closestIndx1) > tPDUSizeWithCrc)
      closestIndx2 = closestIndx1-1;
    else
      closestIndx2 = closestIndx1+1; 
    
    if(closestIndx2==-1 || closestIndx2==PDUSizeWithCrc.length())
    {
      PDUSizeIndx=closestIndx1;
      blerToReturn =  blerCC(indx)(PDUSizeIndx,sinr_indx);
    }
    else
    {
      double bler1=blerCC(indx)(closestIndx1,sinr_indx);
      double bler2=blerCC(indx)(closestIndx2,sinr_indx);
      blerToReturn = bler1 + (bler2 - bler1)*(((double)tPDUSizeWithCrc - (double)PDUSizeWithCrc(closestIndx1))/((double)PDUSizeWithCrc(closestIndx2)-(double)PDUSizeWithCrc(closestIndx1)));
    }
  }
  else
  {
    blerToReturn = blerCC(indx)(PDUSizeIndx,sinr_indx);
  }
  
  return blerToReturn;
  
}

int AWGNTablesConvCoder::aggLevelSelect(ivec CQIs,int tPDUSizeWithCrc){
  
  vec SINRs(CQIs.length());
  if(CQIs.length()>0)
  {
    for(int i =0 ;i < CQIs.length(); i++)
    {
      SINRs(i) = inv_dB(getSINRIndBfromCQI(CQIs(i)));
    }
  }
  else
  {
    cout<<"[both:] CQIs length should be at least one "<<endl;abort();
  }
  
  double SinrIndB = mmibToSinr(_MODULATION_SCHEME_64_QAM_,sinrToEffMMIB(SINRs,_MODULATION_SCHEME_64_QAM_));

  int aggLevelCount = aggLevels.length();
  vec BLER(aggLevelCount);
  vec spec_eff(aggLevelCount);
  
  for(int aggIndx = 0; aggIndx < aggLevelCount; aggIndx++)
  {
    BLER(aggIndx) = getErrorProbabilityForPDCCH( aggLevels(aggIndx), SinrIndB, tPDUSizeWithCrc );
    
    if(BLER(aggIndx) >= 0.01)
      spec_eff(aggIndx) = -1.0/aggLevels(aggIndx);
    else
      spec_eff(aggIndx) = 1.0/aggLevels(aggIndx);
  }

  ivec aggLevel_sorted = sort_index(spec_eff);
  int aggLevel = aggLevels(aggLevel_sorted(aggLevelCount-1));
  return aggLevel;
  
}


